import { defineConfig } from './config'
import type { PackageConfig } from './config'

export interface GeneratePackageEntriesOptions {
  // Specifier prefix resolving to Pages CMS `src/`; the application build aliases `#/`.
  coreImportPrefix?: string
}

export interface PackageEntries {
  server: string
  client: string
  shared: string
}

const HEADER =
  '// Generated by Pages CMS from the package configuration. Do not edit.'

function literal(value: unknown) {
  // JSON is a valid JavaScript expression (ES2019+); paths and IDs are pre-validated.
  return JSON.stringify(value)
}

export function generatePackageEntries(
  input: PackageConfig,
  { coreImportPrefix = '#/' }: GeneratePackageEntriesOptions = {},
): PackageEntries {
  if (!coreImportPrefix.endsWith('/') || /["'\\\n\r]/.test(coreImportPrefix))
    throw new Error('Invalid core import prefix')
  const config = defineConfig(input)
  const core = (path: string) => literal(`${coreImportPrefix}${path}`)

  const serverImports: string[] = []
  const serverPlugins: string[] = []
  const clientImports: string[] = []
  const clientPlugins: string[] = []
  const sharedImports: string[] = []
  const sharedPlugins: string[] = []

  config.plugins.forEach((plugin, index) => {
    if (plugin.server) {
      serverImports.push(`import server${index} from ${literal(plugin.server)}`)
      serverPlugins.push(
        `    instantiateServerPlugin(${literal(plugin.id)}, server${index}, ${literal(plugin.options)}, { publicOptions: ${literal(plugin.publicOptions)}, target: ${literal(config.target)} }),`,
      )
    }
    if (plugin.shared || plugin.client) {
      if (plugin.shared)
        clientImports.push(
          `import shared${index} from ${literal(plugin.shared)}`,
        )
      if (plugin.shared) {
        sharedImports.push(
          `import shared${index} from ${literal(plugin.shared)}`,
        )
        sharedPlugins.push(
          `    instantiateClientPlugin(${literal(plugin.id)}, shared${index}, undefined, ${literal(plugin.publicOptions)}),`,
        )
      }
      if (plugin.client)
        clientImports.push(
          `import client${index} from ${literal(plugin.client)}`,
        )
      // Never emit server options or server module paths into the client entry.
      clientPlugins.push(
        `    instantiateClientPlugin(${literal(plugin.id)}, ${plugin.shared ? `shared${index}` : 'undefined'}, ${plugin.client ? `client${index}` : 'undefined'}, ${literal(plugin.publicOptions)}),`,
      )
    }
  })

  const server = [
    HEADER,
    `import { definePagesCmsServerDeployment } from ${core('deployment/contracts/server.server')}`,
    `import { DEPLOYMENT_API_VERSION } from ${core('deployment/contracts/version')}`,
    `import { instantiateServerPlugin, withDefaultEmail } from ${core('package/runtime.server')}`,
    ...serverImports,
    '',
    'export default definePagesCmsServerDeployment({',
    '  apiVersion: DEPLOYMENT_API_VERSION,',
    '  plugins: withDefaultEmail([',
    ...serverPlugins,
    '  ]),',
    '})',
    '',
  ].join('\n')

  const clientEntry = (imports: string[], plugins: string[]) =>
    [
      HEADER,
      `import { definePagesCmsClientDeployment } from ${core('deployment/contracts/client')}`,
      `import { DEPLOYMENT_API_VERSION } from ${core('deployment/contracts/version')}`,
      `import { instantiateClientPlugin } from ${core('package/runtime')}`,
      ...imports,
      '',
      'export default definePagesCmsClientDeployment({',
      '  apiVersion: DEPLOYMENT_API_VERSION,',
      '  plugins: [',
      ...plugins,
      '  ],',
      '})',
      '',
    ].join('\n')

  return {
    server,
    client: clientEntry(clientImports, clientPlugins),
    shared: clientEntry(sharedImports, sharedPlugins),
  }
}
